import test from 'node:test';
import assert from 'node:assert';
import { roundCents, formatEuros, parseEuros, convert, formatMoney, RATES } from '../src/money.js';

test('roundCents', async (t) => {
  await t.test('rounds half to even (banker\'s rounding)', () => {
    assert.strictEqual(roundCents(124.5), 124);
    assert.strictEqual(roundCents(125.5), 126);
    assert.strictEqual(roundCents(2.4), 2);
    assert.strictEqual(roundCents(-0.5), 0);
  });

  await t.test('handles positive numbers', () => {
    assert.strictEqual(roundCents(1.2), 1);
    assert.strictEqual(roundCents(1.8), 2);
    assert.strictEqual(roundCents(1.5), 2);
  });

  await t.test('handles negative numbers', () => {
    assert.strictEqual(roundCents(-1.2), -1);
    assert.strictEqual(roundCents(-1.8), -2);
    assert.strictEqual(roundCents(-1.5), -2);
  });
});

test('formatEuros', async (t) => {
  await t.test('formats positive amounts', () => {
    assert.strictEqual(formatEuros(0), '€0.00');
    assert.strictEqual(formatEuros(100), '€1.00');
    assert.strictEqual(formatEuros(12345), '€123.45');
    assert.strictEqual(formatEuros(1234567), '€12,345.67');
  });

  await t.test('formats negative amounts with minus sign', () => {
    assert.strictEqual(formatEuros(-5), '-€0.05');
    assert.strictEqual(formatEuros(-12345), '-€123.45');
  });

  await t.test('includes thousands separators', () => {
    assert.strictEqual(formatEuros(1000000), '€10,000.00');
    assert.strictEqual(formatEuros(123456789), '€1,234,567.89');
  });
});

test('parseEuros', async (t) => {
  await t.test('parses valid euro amounts', () => {
    const r1 = parseEuros('12');
    assert.strictEqual(r1.ok, true);
    assert.strictEqual(r1.value, 1200);

    const r2 = parseEuros('12.5');
    assert.strictEqual(r2.ok, true);
    assert.strictEqual(r2.value, 1250);

    const r3 = parseEuros('1,234.56');
    assert.strictEqual(r3.ok, true);
    assert.strictEqual(r3.value, 123456);
  });

  await t.test('rejects invalid formats', () => {
    const r1 = parseEuros('abc');
    assert.strictEqual(r1.ok, false);
    assert.strictEqual(r1.error, 'AMOUNT_INVALID');

    const r2 = parseEuros('12,34.56');
    assert.strictEqual(r2.ok, false);

    const r3 = parseEuros('12.567');
    assert.strictEqual(r3.ok, false);
  });

  await t.test('handles leading/trailing whitespace', () => {
    const r = parseEuros('  12.34  ');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, 1234);
  });
});

test('RATES', async (t) => {
  await t.test('defines exchange rates', () => {
    assert.strictEqual(RATES.EUR, 1);
    assert.strictEqual(RATES.USD, 1.085);
    assert.strictEqual(RATES.GBP, 0.8425);
  });
});

test('convert', async (t) => {
  await t.test('converts EUR to EUR (1:1)', () => {
    const r = convert(100, 'EUR');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, 100);
  });

  await t.test('converts EUR to USD', () => {
    const r = convert(10000, 'USD');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, 10850);
  });

  await t.test('converts EUR to GBP', () => {
    const r = convert(10000, 'GBP');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, 8425);
  });

  await t.test('rounds currency conversion', () => {
    const r = convert(12345, 'USD');
    assert.strictEqual(r.ok, true);
    const expected = Math.round((12345 / 100) * 1.085 * 100);
    assert.strictEqual(r.value, expected);
  });

  await t.test('handles zero amount', () => {
    const r = convert(0, 'USD');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, 0);
  });

  await t.test('handles negative amounts', () => {
    const r = convert(-10000, 'USD');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, -10850);
  });

  await t.test('rejects unknown currency', () => {
    const r = convert(10000, 'JPY');
    assert.strictEqual(r.ok, false);
    assert.strictEqual(r.error, 'UNKNOWN_CURRENCY');
  });

  await t.test('is case sensitive for currency codes', () => {
    const r = convert(10000, 'usd');
    assert.strictEqual(r.ok, false);
  });

  await t.test('converts large amounts accurately', () => {
    const r = convert(1000000, 'USD');
    assert.strictEqual(r.ok, true);
    assert.strictEqual(r.value, 1085000);
  });
});

test('formatMoney', async (t) => {
  await t.test('formats EUR amounts with euro symbol', () => {
    assert.strictEqual(formatMoney(0, 'EUR'), '€0.00');
    assert.strictEqual(formatMoney(100, 'EUR'), '€1.00');
    assert.strictEqual(formatMoney(12345, 'EUR'), '€123.45');
  });

  await t.test('formats USD amounts with dollar sign', () => {
    assert.strictEqual(formatMoney(0, 'USD'), '$0.00');
    assert.strictEqual(formatMoney(108500, 'USD'), '$1,085.00');
  });

  await t.test('formats GBP amounts with pound sign', () => {
    assert.strictEqual(formatMoney(0, 'GBP'), '£0.00');
    assert.strictEqual(formatMoney(84250, 'GBP'), '£842.50');
  });

  await t.test('includes thousands separators', () => {
    assert.strictEqual(formatMoney(10000000, 'EUR'), '€100,000.00');
    assert.strictEqual(formatMoney(10000000, 'USD'), '$108,500.00');
    assert.strictEqual(formatMoney(10000000, 'GBP'), '£84,250.00');
  });

  await t.test('formats negative amounts with minus sign', () => {
    assert.strictEqual(formatMoney(-100, 'EUR'), '-€1.00');
    assert.strictEqual(formatMoney(-108500, 'USD'), '-$1,085.00');
    assert.strictEqual(formatMoney(-84250, 'GBP'), '-£842.50');
  });

  await t.test('handles unknown currency', () => {
    assert.strictEqual(formatMoney(10000, 'JPY'), 'Unknown currency');
  });

  await t.test('converts EUR to USD correctly', () => {
    const amount = formatMoney(100, 'USD');
    assert.match(amount, /\$1\.09/);
  });

  await t.test('converts EUR to GBP correctly', () => {
    const amount = formatMoney(100, 'GBP');
    assert.match(amount, /£0\.84/);
  });

  await t.test('handles zero in any currency', () => {
    assert.strictEqual(formatMoney(0, 'EUR'), '€0.00');
    assert.strictEqual(formatMoney(0, 'USD'), '$0.00');
    assert.strictEqual(formatMoney(0, 'GBP'), '£0.00');
  });

  await t.test('formats large amounts with proper precision', () => {
    const usd = formatMoney(123456789, 'USD');
    assert.match(usd, /\$1,338,\d{3}\.\d{2}/);
  });
});

test('convert and formatMoney integration', async (t) => {
  await t.test('convert result can be formatted', () => {
    const converted = convert(10000, 'USD');
    assert.strictEqual(converted.ok, true);
    const formatted = formatMoney(10000, 'USD');
    assert.match(formatted, /\$108\.50/);
  });

  await t.test('round trip preserves approximate value', () => {
    const original = 50000;
    const usdResult = convert(original, 'USD');
    const gbpResult = convert(original, 'GBP');

    assert.strictEqual(usdResult.ok, true);
    assert.strictEqual(gbpResult.ok, true);

    const usdEuros = Math.round(usdResult.value / 1.085);
    const gbpEuros = Math.round(gbpResult.value / 0.8425);

    assert.strictEqual(usdEuros, original);
    assert.strictEqual(gbpEuros, original);
  });
});

